-- =============================================================================
-- Migración: sincronizar la identity de historialauditoria.idauditoria
-- Fecha: 2026-10-04 · Autora: Marcela Chalco Soliz (HU16 / Sprint 2)
--
-- Por qué: AuditoriaService calculaba el id como MAX(idauditoria) + 1. Con dos
-- registros al mismo tiempo, ambos tomaban el mismo id, uno fallaba por PK
-- duplicada y esa auditoría se perdía sin aviso (solo quedaba en el log).
--
-- Estado real de la BD (verificado el 2026-10-04): idauditoria es
-- integer GENERATED BY DEFAULT AS IDENTITY, sin default extra.
-- Como el código siempre mandaba el id a mano, la sequence interna de la
-- identity NUNCA avanzó (sigue en 1). Si el código nuevo (que deja que
-- PostgreSQL genere el id) corriera sin este script, intentaría usar 1, 2, 3...
-- que ya existen y TODAS las auditorías fallarían.
--
-- Este script NO cambia la estructura de la tabla: solo mueve el contador
-- de la identity hasta MAX(idauditoria) + 1.
--
-- Cómo ejecutar: Supabase > SQL Editor. Ejecutar cada consulta POR SEPARADO
-- (el editor solo muestra el resultado de la última). Hacerlo en CADA base
-- que use el backend, ANTES de levantar el backend con el código nuevo.
-- =============================================================================


-- PASO 1 · Diagnóstico (solo lectura)

-- 1a. Tipo de columna. Esperado: is_identity = YES, identity_generation = BY DEFAULT
SELECT column_name, data_type, column_default, is_identity, identity_generation
FROM information_schema.columns
WHERE table_schema = 'public'
  AND table_name   = 'historialauditoria'
  AND column_name  = 'idauditoria';

-- 1b. Filas e id máximo (2026-10-04: 1217 filas, máximo 1217)
SELECT COUNT(*) AS filas, MAX(idauditoria) AS id_maximo
FROM public.historialauditoria;

-- 1c. Nombre y valor actual de la sequence interna de la identity
SELECT pg_get_serial_sequence('public.historialauditoria', 'idauditoria') AS secuencia;

-- 1d. Valor actual de la sequence de la identity. OJO: se llama ..._seq1;
--     existe otra "historialauditoria_idauditoria_seq" (sin 1) que es vieja,
--     no la usa la columna y NO se toca.
SELECT last_value, is_called FROM public.historialauditoria_idauditoria_seq1;


-- PASO 2 · Migración (ejecutar estas 4 líneas juntas)
BEGIN;
LOCK TABLE public.historialauditoria IN EXCLUSIVE MODE;
SELECT setval(pg_get_serial_sequence('public.historialauditoria', 'idauditoria'),
              COALESCE((SELECT MAX(idauditoria) FROM public.historialauditoria), 0) + 1,
              false);
COMMIT;


-- PASO 3 · Verificación (solo lectura)
-- Esperado: last_value = id_maximo + 1 (1218) e is_called = false
SELECT last_value, is_called FROM public.historialauditoria_idauditoria_seq1;


-- PASO 4 · Resincronizar (ejecutar UNA vez, cuando TODO el equipo ya tenga el
-- código nuevo). Corrige el contador si alguien con código viejo insertó
-- auditorías (con id a mano) después del PASO 2. Es el mismo setval del PASO 2.
-- SELECT setval(pg_get_serial_sequence('public.historialauditoria', 'idauditoria'),
--               COALESCE((SELECT MAX(idauditoria) FROM public.historialauditoria), 0) + 1,
--               false);


-- REVERTIR: no hace falta. El script no cambia la estructura; el código viejo
-- (que manda el id a mano) sigue funcionando con la identity sincronizada.
